{
  "title": "Does button B sell more?",
  "setting": "Day 3 at Aurora Shop",
  "mission": "Decide whether the new checkout button really sells more or if the gap is just chance.",
  "deadline": "Meeting with {{product}} today at 3:00 p.m.",
  "panels": [
    {
      "title": "Checkout A/B test results",
