        {
          "label": "Version A sales",
          "value": "3.4%",
          "note": "Control button"
        },
        {
          "label": "Version B sales",
          "value": "3.9%",
          "note": "New green button"
        },
        {
          "label": "Visits",
          "value": "1,200",
          "note": "Per version so far"
        }
      ],
      "note": "Live for 1 day on the Aurora Shop website."
    }
  ],
  "team": [
    {
      "id": "product",
      "role": "Product manager",
      "expertise": "Wants to launch the green button immediately to boost sales.",
      "ai": false
    },
    {
      "id": "data",
      "role": "Data analyst",
      "expertise": "Knows numbers and metrics inside out.",
      "ai": false
    },
    {
      "id": "ai",
      "role": "AI Assistant",
      "expertise": "Runs quick calculations and checks p-values.",
      "ai": true
    }
  ],
  "meters": [
    {
      "id": "confidence",
      "label": "Certainty in the result",
      "start": 40,
      "goodWhen": "high"
    },
    {
      "id": "patience",
      "label": "{{product}}'s patience",
      "start": 70,
      "goodWhen": "high"
    }
  ],
  "skills": [
    {
      "id": "tell-diff",
      "name": "Tell a real difference from chance",
      "practice": "Decide whether a gap between two groups could be random variation."
    },
    {
      "id": "sample-size",
      "name": "Choose a sample size",
      "practice": "Calculate how many observations a comparison needs before trusting it."
    },
    {
      "id": "explain-test",
      "name": "Explain a test result",
      "practice": "Explain a test result to people who aren't data people in one clear sentence."
    }
  ],
  "startNodeId": "first-check",
  "nodes": [
    {
      "id": "first-check",
      "messages": [
        {
          "from": "product",
          "text": "Version B is ahead by half a percent! Can we roll it out to everyone today?"
        },
        {
          "from": "data",
          "text": "We only ran it for one day. With 1,200 visits, small swings happen all the time."
        }
      ],
      "prompt": "What do you do first?",
      "choices": [
        {
          "id": "ask-ai",
          "text": "Ask the AI assistant to check if the difference is real or just chance.",
          "quality": "strong",
          "replies": [
            {
              "from": "ai",
              "text": "I ran a check on the numbers. The p-value is 0.22, which means this gap happens often by pure chance."
            }
          ],
          "effects": [
            {
              "meter": "confidence",
              "change": 25
            },
            {
              "meter": "patience",
              "change": -10
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "tell-diff",
              "kind": "good",
              "text": "You checked whether the gap could be chance before making a call.",
              "example": null
            }
          ],
          "next": "wait-decision"
        },
        {
          "id": "launch-now",
          "text": "Agree with {{product}} and launch version B right away.",
          "quality": "weak",
          "replies": [
            {
              "from": "data",
              "text": "That feels rushed. We might be replacing our main button based on a lucky streak."
            }
          ],
          "effects": [
            {
              "meter": "confidence",
              "change": -30
            },
            {
              "meter": "patience",
              "change": 20
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "tell-diff",
              "kind": "improve",
              "text": "You launched before checking if the difference was just random noise.",
              "example": "Let's wait a bit longer to be sure the difference is real."
            }
          ],
          "next": "early-ending"
        },
        {
          "id": "wait-longer",
          "text": "Tell {{product}} we need to collect more data before deciding.",
          "quality": "fair",
          "replies": [
            {
              "from": "product",
              "text": "Fine, but every day we wait is sales we might be missing."
            }
          ],
          "effects": [
            {
              "meter": "confidence",
              "change": 10
            },
            {
              "meter": "patience",
              "change": -20
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "sample-size",
              "kind": "good",
              "text": "You recognized that the current sample size was too small for a firm decision.",
              "example": null
            }
          ],
          "next": "wait-decision"
        }
      ]
    },
    {
      "id": "wait-decision",
      "messages": [
        {
          "from": "data",
          "text": "If we wait three more days, we will have enough visitors for a reliable sample size."
        },
        {
          "from": "product",
          "text": "Do we really need to wait three whole days?"
        }
      ],
      "prompt": "How do you handle the timeline?",
      "choices": [
        {
          "id": "wait-three-days",
          "text": "Wait three more days to gather enough visitors for a solid test.",
          "quality": "strong",
          "replies": [
            {
              "from": "ai",
              "text": "Great choice. A larger sample size washes out random daily habits."
            }
          ],
          "effects": [
            {
              "meter": "confidence",
              "change": 30
            },
            {
              "meter": "patience",
              "change": -15
            }
          ],
          "timeJump": {
            "label": "Three days later",
            "panel": {
              "title": "Final A/B test results",
              "metrics": [
                {
                  "label": "Version A sales",
                  "value": "3.5%",
                  "note": "Control button"
                },
                {
                  "label": "Version B sales",
                  "value": "3.6%",
                  "note": "New green button"
                },
                {
                  "label": "Visits",
                  "value": "5,000",
                  "note": "Per version total"
                }
              ],
              "note": "Test completed with 5,000 visits per version."
            }
          },
          "notes": [
            {
              "skill": "sample-size",
              "kind": "good",
              "text": "You waited for an adequate sample size, giving the test time to reveal the truth.",
              "example": null
            }
          ],
          "next": "final-explanation"
        },
        {
          "id": "stop-now",
          "text": "Call the test complete now and make the call with today's data.",
          "quality": "weak",
          "replies": [
            {
              "from": "data",
              "text": "Stopping early without enough data usually gives us false positives."
            }
          ],
          "effects": [
            {
              "meter": "confidence",
              "change": -20
            },
            {
              "meter": "patience",
              "change": 10
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "sample-size",
              "kind": "improve",
              "text": "You stopped the test too early before collecting enough observations.",
              "example": "We should let it run until we reach our target sample size."
            }
          ],
          "next": "early-ending"
        }
      ]
    },
    {
      "id": "final-explanation",
      "messages": [
        {
          "from": "data",
          "text": "Now that we have 5,000 visits per version, the gap shrank to just 0.1% and the p-value is 0.45."
        },
        {
          "from": "product",
          "text": "Wait, what does that mean? Should we launch or not?"
        }
      ],
      "prompt": "How do you explain the final result to {{product}}?",
      "choices": [
        {
          "id": "plain-explanation",
          "text": "Explain simply that the tiny difference is most likely random luck, so we should keep the original button.",
          "quality": "strong",
          "replies": [
            {
              "from": "product",
              "text": "Ah, I get it now. Thanks for saving us from changing things for no real reason!"
            }
          ],
          "effects": [
            {
              "meter": "confidence",
              "change": 25
            },
            {
              "meter": "patience",
              "change": 15
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "explain-test",
              "kind": "good",
              "text": "You translated technical test results into plain terms that a colleague easily understood.",
              "example": "The small gap is just random variation, so keeping our current button is safer."
            }
          ],
          "next": "success-ending"
        },
        {
          "id": "jargon-explanation",
          "text": "Explain using statistical jargon about p-values and null hypotheses.",
          "quality": "weak",
          "replies": [
            {
              "from": "product",
              "text": "That sounds very complicated. Can we just roll a dice instead?"
            }
          ],
          "effects": [
            {
              "meter": "confidence",
              "change": -10
            },
            {
              "meter": "patience",
              "change": -25
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "explain-test",
              "kind": "improve",
              "text": "You used heavy jargon instead of clear everyday language.",
              "example": "Because our p-value is high, we failed to reject the null hypothesis."
            }
          ],
          "next": "confused-ending"
        }
      ]
    }
  ],
  "endings": [
    {
      "id": "success-ending",
      "outcome": "You guided the team through proper hypothesis testing. By waiting for an adequate sample size and explaining the results clearly, Aurora Shop avoided making changes based on random noise."
    },
    {
      "id": "early-ending",
      "outcome": "You made a call before gathering enough data. The new button went live based on a lucky streak, and sales actually dropped slightly the following week as the novelty wore off."
    },
    {
      "id": "confused-ending",
      "outcome": "The meeting ended in confusion over statistical terms. {{product}} went ahead and launched the button anyway out of frustration, leaving the team without clear insights."
    }
  ],
  "summary": [
    "Distinguish between real differences and random chance in A/B tests.",
    "Calculate and wait for a proper sample size before drawing conclusions.",
    "Explain test results clearly to colleagues without relying on jargon."
  ]
}

{
  "title": "E se a luz fosse feita de bolinhas de gude?",
  "setting": "Universiverso imaginário",
  "mission": "Descubra como os **pacotes de energia** mudam a cor e o brilho das coisas ao seu redor.",
  "deadline": null,
  "panels": [],
  "team": [
    {
      "id": "fisica",
      "role": "Física curiosa",
      "expertise": "Adora explicar mistérios do universo de forma simples",
      "ai": false
    },
