    {
      "id": "curiosidade",
      "label": "Curiosidade sobre o universo",
      "start": 50,
      "goodWhen": "high"
    }
  ],
  "skills": [
    {
      "id": "pacotes",
      "name": "Explicar que a energia vem em pacotes",
      "practice": "Explique para alguém em uma frase por que a luz não é um jato contínuo de água."
    },
    {
      "id": "onda",
      "name": "Reconhecer a dualidade onda-partícula",
      "practice": "Descreva um exemplo do dia a dia onde algo parece onda e partícula ao mesmo tempo."
    }
  ],
  "startNodeId": "escolha-luz",
  "nodes": [
    {
      "id": "escolha-luz",
      "messages": [
        {
          "from": "fisica",
          "text": "{{amigo}} está tentando entender por que a luz de uma lâmpada vermelha não consegue arrancar elétrons de um metal, mas a azul consegue."
        },
        {
          "from": "amigo",
          "text": "Para mim, luz é só claridade contínua. Por que a cor vermelha falha?"
        }
      ],
      "prompt": "Como você explica o comportamento da luz para {{amigo}}?",
      "choices": [
        {
          "id": "pacotinhos",
          "text": "Dizer que a luz chega em pacotinhos chamados quanta, e o vermelho tem pacotes fracos demais.",
          "quality": "strong",
          "replies": [
            {
              "from": "fisica",
              "text": "Exatamente! Cada fóton é um pacote indivisível de energia."
            },
            {
              "from": "amigo",
              "text": "Ah, entendi! É como tentar derrubar um pino de boliche com bolinhas de gude em vez de uma bola pesada."
            }
          ],
          "effects": [
            {
              "meter": "curiosidade",
              "change": 25
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "pacotes",
              "kind": "good",
              "text": "Você usou a ideia central de que a energia da luz não é contínua, mas dividida em partes.",
              "example": null
            }
          ],
          "next": "escolha-onda"
        },
        {
          "id": "calor",
          "text": "Explicar que a luz vermelha apenas esquenta menos o metal.",
          "quality": "weak",
          "replies": [
            {
              "from": "fisica",
              "text": "Não é bem sobre calor, mas sobre a energia de cada pacote individual de luz."
            },
            {
              "from": "amigo",
              "text": "Mas se eu deixar a luz vermelha acesa por muito tempo, não deveria funcionar?"
            }
          ],
          "effects": [
            {
              "meter": "curiosidade",
              "change": -10
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "pacotes",
              "kind": "improve",
              "text": "Lembre-se de que a energia vem em pacotes mínimos por partícula, independentemente do tempo de exposição.",
              "example": "A luz vermelha tem pacotes fracos demais, não importa quanto tempo fique acesa."
            }
          ],
          "next": "escolha-onda"
        }
      ]
    },
    {
      "id": "escolha-onda",
      "messages": [
        {
          "from": "fisica",
          "text": "Agora pense em como a luz viaja pelo espaço e atravessa frestas estreitas."
        },
        {
          "from": "amigo",
          "text": "Se a luz são pacotes como bolinhas, ela deveria fazer apenas uma linha reta, né?"
        }
      ],
      "prompt": "O que você responde sobre a forma como a luz viaja?",
      "choices": [
        {
          "id": "dupla-face",
          "text": "Explicar que ela viaja espalhada como onda, mas interage batendo como partícula.",
          "quality": "strong",
          "replies": [
            {
              "from": "fisica",
              "text": "Perfeito. Essa é a grande surpresa do mundo quântico!"
            },
            {
              "from": "amigo",
              "text": "Nossa, então a luz tem duas caras! Viaja como maré e bate como pedra."
            }
          ],
          "effects": [
            {
              "meter": "curiosidade",
              "change": 25
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "onda",
              "kind": "good",
              "text": "Você conectou perfeitamente os dois lados da dualidade onda-partícula.",
              "example": null
            }
          ],
          "next": "fim-sucesso"
        },
        {
          "id": "so-particula",
          "text": "Dizer que ela é apenas um conjunto de pequenas pedras voando em linha reta.",
          "quality": "weak",
          "replies": [
            {
              "from": "fisica",
              "text": "Isso explicaria os choques, mas não explicaria como a luz forma padrões de interferência."
            },
            {
              "from": "amigo",
              "text": "Fica difícil entender como ela faz curvas e contorna obstáculos então."
            }
          ],
          "effects": [
            {
              "meter": "curiosidade",
              "change": -10
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "onda",
              "kind": "improve",
              "text": "Lembre-se de que a luz precisa do comportamento de onda para explicar certos fenômenos de propagação.",
              "example": "A luz viaja como onda e se comporta como partícula ao colidir."
            }
          ],
          "next": "fim-parcial"
        }
      ]
    }
  ],
  "endings": [
    {
      "id": "fim-sucesso",
      "outcome": "{{amigo}} entendeu que a energia vem em pacotes chamados quanta e que a luz transita entre ondas e partículas com muita elegância."
    },
    {
      "id": "fim-parcial",
      "outcome": "{{amigo}} ficou com algumas dúvidas sobre o comportamento da luz, mas já percebeu que o mundo microscópico é bem diferente do nosso dia a dia."
    }
  ],
  "summary": [
    "A energia da luz e da matéria é distribuída em pacotes discretos chamados quanta.",
    "A luz exibe uma fascinante dualidade, comportando-se ora como onda, ora como partícula."
  ]
}

